export type ThemeArt = keyof typeof themeVectors;

export function createThemeArt(key: ThemeArt, width: string, height: string | number, fit = 'none'): SVGSVGElement {
  const artwork = themeVectors[key];
  const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
  svg.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
  svg.setAttribute('viewBox', artwork.viewBox);
  svg.setAttribute('preserveAspectRatio', fit);
  svg.setAttribute('width', width);
  svg.setAttribute('height', String(height));
  svg.setAttribute('data-inkflow-art', key);
  svg.setAttribute('data-inkflow-decoration', 'true');
  svg.setAttribute('aria-hidden', 'true');
  // Only build-time assets enter this factory; authored SVG stays outside the Markdown allowlist.
  svg.innerHTML = artwork.paths;
  return svg;
}
